L22_1 = "\227\129\149\227\129\130\227\128\129\232\133\185\227\129\148\227\129\151\227\130\137\227\129\136\227\130\130\227\129\151\227\129\159\227\129\151\227\128\130\227\129\157\227\130\141\227\129\157\227\130\141\231\148\168\228\187\182\227\130\146\232\169\177\227\129\151\227\129\166\227\129\191\227\130\139\227\129\139\227\129\174\227\129\134\227\128\130"
